<?php
namespace Database\Seeders;use App\Models\{RepairMaintenanceRecord,Vehicle,Driver};use Illuminate\Database\Seeder;
class RepairMaintenanceRecordSeeder extends Seeder{public function run():void{$vehicles=Vehicle::pluck('id');$drivers=Driver::pluck('id');foreach(['Maintenance','Oil Change','Brake Service','Tire Service','Mechanical Repair','Battery Replacement','Electrical Repair','Inspection'] as $i=>$type){if(!$vehicles->count())break;RepairMaintenanceRecord::updateOrCreate(['job_order_no'=>'JO-2024-'.str_pad(56-$i,4,'0',STR_PAD_LEFT)],['vehicle_id'=>$vehicles[$i%$vehicles->count()],'driver_id'=>$drivers->count()?$drivers[$i%$drivers->count()]:null,'job_date'=>now()->subDays($i+1)->toDateString(),'job_type'=>$type,'priority'=>['Medium','Low','High'][$i%3],'work_status'=>'Completed','completed_date'=>now()->subDays($i+1)->toDateString(),'service_provider'=>'AutoFix Service Center','contact_person'=>'Mike Johnson','provider_phone'=>'+1 (416) 555-2000','invoice_no'=>'INV-2024-'.(4567-$i),'subtotal'=>[650,120,480,350,920,150,610,85][$i],'sales_tax'=>0,'discount'=>0,'total_paid'=>[734.5,120,480,350,920,150,610,85][$i],'payment_method'=>'Credit Card','description'=>strtolower($type).' completed and vehicle safety checked.','parts'=>[]]);}}}
